<template>
<section><div class="page-head"><div><span class="eyebrow">Configure add-on</span><h1 class="page-title">{{($root.selectedAddonData||{}).name}} settings</h1><p class="muted">Settings are stored locally in this browser.</p></div><button class="button-secondary" @click="$emit('navigate','addons')">← Add-ons</button></div>
<div v-if="$root.route.addonId==='iptv_simple'" class="card"><div class="tabs"><button class="active">Settings</button><button>EPG</button></div><div class="form-grid"><div class="field"><label for="m3u">Name</label><input id="m3u" class="input" v-model="state.m3uUrl" placeholder="My IPTV playlist name"></div><div class="field"><label for="m3uurl">M3U URL</label><input id="m3uurl" class="input" type="url" placeholder="https://example.com/playlist.m3u"></div><div class="field"><label for="epgname">EPG Name</label><input id="epgname" class="input" placeholder="My EPG guide"></div><div class="field"><label for="epgurl">EPGXML URL</label><input id="epgurl" class="input" type="url" placeholder="https://example.com/guide.xml"></div><button class="button" @click="$emit('action',{action:'save-iptv'})">OK</button></div><p class="muted">Only enter playlist URLs you trust. This client does not provide IPTV streams.</p></div>
<div v-else-if="$root.route.addonId==='iptv_manager'" class="card"><h2>IPTV Manager</h2><p class="muted">IPTV Manager redirects you to the IPTV Simple Client settings.</p><button class="button" @click="$emit('navigate','addon/iptv_manager/redirect?addon_name=IPTV%20Simple%20Client')">Open IPTV Simple Client settings</button></div>
<div v-else-if="$root.route.addonId==='youtube'" class="card"><h2>YouTube account</h2><p class="muted">Link your TV with a one-time code. Sign-in is completed securely on Google.</p><a class="button" href="https://www.google.com/device" target="_blank" rel="noopener">Go to google.com/device ↗</a><p><a href="#addon/settings_youtube/signin">YouTube Sign In</a></p><button class="quiet" @click="$emit('navigate','javascript:youtube(0)sign_out')">Sign Out</button></div>
<div v-else-if="$root.route.addonId==='radio_browser'" class="card"><h2>Radio-Browser.info</h2><p class="muted">Browse live radio, search stations, and play available streams.</p><p><a href="https://de1.api.radio-browser.info/json/" target="_blank" rel="noopener">Radio directory JSON ↗</a></p><div class="row"><button class="button" @click="$emit('navigate','radio')">Open Radio</button><a class="button-secondary" href="https://radio-browser.info/my-profile/404" target="_blank" rel="noopener">My Profile ↗</a><a class="quiet" href="https://radio-browser.info" target="_blank" rel="noopener">Sign in / Exit Radio-Browser.info ↗</a></div></div>
<div v-else-if="$root.route.addonId==='google_drive'||$root.route.addonId==='onedrive'" class="card"><h2>{{($root.selectedAddonData||{}).name}}</h2><p class="muted">Open the secure sign-in page and enter the service code shown below.</p><div class="code">{{$root.route.addonId==='google_drive'?'DRIVEG10':'DRIVEMICROSOFT12'}}</div><a class="button" :href="'https://drive.signincloud.com/#code?utm_source=logoremakefour_mediacenter&code_drive='+($root.route.addonId==='google_drive'?'DRIVEG10':'DRIVEMICROSOFT12')" target="_blank" rel="noopener">Scan to QR / Open sign-in ↗</a></div>
<div v-else class="card"><h2>Settings</h2><p class="muted">No settings are available for this add-on yet.</p></div></section>
</template>
